    g.CameraUseCameraPoint(cam, sNone, 1.0f, 1, 2);
    g.CameraUseCameraPoint(cam, sDead, 1.0f, 1, 2);
    g.CameraUseCameraPoint(cam, sNoPhys, 1.0f, 1, 2);
    if (g.calls != 0) { std::printf("00891070_TEST FAIL\n"); return 1; }
